  1	import MiniSearch from "minisearch";
  2	import { type DiscourseNode } from "~/utils/getDiscourseNodes";
  3	import {
  4	  DISCOURSE_NODE_MIN_SEARCH_SCORE,
  5	  DISCOURSE_NODE_MINI_SEARCH_OPTIONS,
  6	  DISCOURSE_NODE_SEARCH_METADATA_PULL,
  7	  getPulledDiscourseNodeAuthorName,
  8	  getPulledDiscourseNodeTitle,
  9	  getPulledDiscourseNodeUid,
 10	  queryDiscourseNodesByFormat,
 11	} from "~/utils/discourseNodeSearch";
 12	import {
 13	  MAX_RESULTS,
 14	  type ScoredSearchResult,
 15	  type SearchResult,
 16	} from "~/utils/discourseNodeSearchTypes";
 17	
 18	export type {
 19	  ScoredSearchResult,
 20	  SearchResult,
 21	} from "~/utils/discourseNodeSearchTypes";
 22	
 23	export const DEBOUNCE_MS = 250;
 24	export { MAX_RESULTS };
 25	
 26	export const getSearchKeywords = (searchTerm: string): string[] =>
 27	  searchTerm.split(/\s+/).filter(Boolean);
 28	
 29	export type SortField = "relevance" | "alphabetical" | "dateCreated" | "author";
 30	export type SortDirection = "asc" | "desc";
 31	
 32	export type SortConfig = {
 33	  field: SortField;
 34	  direction: SortDirection;
 35	};
 36	
 37	export const DEFAULT_SORT_CONFIG: SortConfig = {
 38	  field: "relevance",
 39	  direction: "desc",
 40	};
 41	
 42	export const SORT_FIELD_LABELS: Record<SortField, string> = {
 43	  relevance: "Relevance",
 44	  alphabetical: "Alphabetical",
 45	  dateCreated: "Date created",
 46	  author: "Author",
 47	};
 48	
 49	export type DockedSearchState = {
 50	  query: string;
 51	  results: SearchResult[];
 52	  selectedNodeTypeIds: string[];
 53	  sort: SortConfig;
 54	  windowId?: string;
 55	  dgSearchId?: string;
 56	};
 57	
 58	type MiniSearchDocument = SearchResult & {
 59	  id: string;
 60	};
 61	
 62	export const formatMetadataDate = (value: string): string => {
 63	  if (!value) return "Unknown";
 64	  const numericValue = Number(value);
 65	  const date = Number.isFinite(numericValue)
 66	    ? new Date(numericValue)
 67	    : new Date(value);
 68	  if (Number.isNaN(date.getTime())) return value;
 69	
 70	  return date.toLocaleDateString(undefined, {
 71	    year: "numeric",
 72	    month: "short",
 73	    day: "numeric",
 74	  });
 75	};
 76	
 77	export const formatBadgeText = (text: string): string =>
 78	  text.replace(/^#/, "").slice(0, 3).toUpperCase();
 79	
 80	export const stripTypePrefix = (title: string): string => {
 81	  const match = title.match(/^\[\[.*?\]\]\s*-\s*(.*)/s);
 82	  return match ? match[1] : title;
 83	};
 84	
 85	export const splitWithHighlights = (
 86	  text: string,
 87	  keywords: string[],
 88	): { text: string; isMatch: boolean }[] => {
 89	  if (!keywords.length) return [{ text, isMatch: false }];
 90	
 91	  const escapedKeywords = keywords.map((keyword) =>
 92	    keyword.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"),
 93	  );
 94	  const regex = new RegExp(`(${escapedKeywords.join("|")})`, "gi");
 95	  const loweredKeywords = new Set(
 96	    keywords.map((keyword) => keyword.toLowerCase()),
 97	  );
 98	
 99	  return text
100	    .split(regex)
101	    .filter(Boolean)
102	    .map((part) => ({
103	      text: part,
104	      isMatch: loweredKeywords.has(part.toLowerCase()),
105	    }));
106	};
107	
108	const queryNodesForType = async (
109	  node: DiscourseNode,
110	): Promise<SearchResult[]> => {
111	  try {
112	    const pulledNodes = await queryDiscourseNodesByFormat({
113	      node,
114	      pullExpression: DISCOURSE_NODE_SEARCH_METADATA_PULL,
115	    });
116	
117	    return pulledNodes
118	      .map((result) => {
119	        const uid = getPulledDiscourseNodeUid(result);
120	        const title = getPulledDiscourseNodeTitle(result);
121	        if (!uid || !title) return null;
122	
123	        return {
124	          uid,
125	          title,
126	          type: node.type,
127	          nodeTypeLabel: node.text,
128	          excerpt: "",
129	          createdAt: String(result[":create/time"] || ""),
130	          lastModified: String(
131	            result[":edit/time"] || result[":create/time"] || "",
132	          ),
133	          authorName: getPulledDiscourseNodeAuthorName(result),
134	        };
135	      })
136	      .filter((result): result is SearchResult => !!result);
137	  } catch (error) {
138	    console.error(`Error querying for node type ${node.type}:`, error);
139	    throw error;
140	  }
141	};
142	
143	export const buildSearchIndex = async (
144	  discourseNodes: DiscourseNode[],
145	): Promise<{
146	  miniSearch: MiniSearch<MiniSearchDocument>;
147	  results: SearchResult[];
148	}> => {
149	  const resultsByType = await Promise.allSettled(
150	    discourseNodes.map(queryNodesForType),
151	  );
152	
153	  const rejected = resultsByType.filter(
154	    (result): result is PromiseRejectedResult => result.status === "rejected",
155	  );
156	  if (discourseNodes.length > 0 && rejected.length === discourseNodes.length) {
157	    throw (
158	      rejected[0]?.reason ??
159	      new Error("Failed to build advanced node search index")
160	    );
161	  }
162	
163	  const results: SearchResult[] = [];
164	  const seenUids = new Set<string>();
165	  for (const resultByType of resultsByType) {
166	    if (resultByType.status !== "fulfilled") continue;
167	    for (const result of resultByType.value) {
168	      if (seenUids.has(result.uid)) continue;
169	      seenUids.add(result.uid);
170	      results.push(result);
171	    }
172	  }
173	
174	  const miniSearch = new MiniSearch<MiniSearchDocument>({
175	    fields: ["title", "nodeTypeLabel"],
176	    storeFields: ["uid", "title", "type", "nodeTypeLabel", "excerpt"],
177	    idField: "id",
178	  });
179	
180	  miniSearch.addAll(results.map((result) => ({ ...result, id: result.uid })));
181	
182	  return { miniSearch, results };
183	};
184	
185	const compareNumbers = (
186	  a: number,
187	  b: number,
188	  direction: SortDirection,
189	): number => (direction === "desc" ? b - a : a - b);
190	
191	const compareStrings = (
192	  a: string,
193	  b: string,
194	  direction: SortDirection,
195	): number => {
196	  const comparison = a.localeCompare(b, undefined, { sensitivity: "base" });
197	  return direction === "desc" ? -comparison : comparison;
198	};
199	
200	const getSortableTitle = (result: SearchResult): string =>
201	  stripTypePrefix(result.title);
202	
203	const getCreatedTime = (result: SearchResult): number =>
204	  Number(result.createdAt) || 0;
205	
206	export const isNonDefaultSort = (sort: SortConfig): boolean =>
207	  sort.field !== DEFAULT_SORT_CONFIG.field ||
208	  sort.direction !== DEFAULT_SORT_CONFIG.direction;
209	
210	export const sortSearchResults = ({
211	  scoredResults,
212	  sort,
213	}: {
214	  scoredResults: ScoredSearchResult[];
215	  sort: SortConfig;
216	}): SearchResult[] => {
217	  // Semantic and MiniSearch results already arrive in their provider's relevance
218	  // order, so relevance sorting only has to reverse it for ascending.
219	  if (sort.field === "relevance") {
220	    const ordered =
221	      sort.direction === "asc" ? [...scoredResults].reverse() : scoredResults;
222	    return ordered.map((entry) => entry.result);
223	  }
224	
225	  const sorted = [...scoredResults];
226	
227	  sorted.sort((aEntry, bEntry) => {
228	    const a = aEntry.result;
229	    const b = bEntry.result;
230	    let comparison = 0;
231	
232	    switch (sort.field) {
233	      case "alphabetical":
234	        comparison = compareStrings(
235	          getSortableTitle(a),
236	          getSortableTitle(b),
237	          sort.direction,
238	        );
239	        break;
240	      case "dateCreated":
241	        comparison = compareNumbers(
242	          getCreatedTime(a),
243	          getCreatedTime(b),
244	          sort.direction,
245	        );
246	        break;
247	      case "author": {
248	        const aAuthor = a.authorName.trim();
249	        const bAuthor = b.authorName.trim();
250	        if (!aAuthor && !bAuthor) comparison = 0;
251	        else if (!aAuthor) comparison = 1;
252	        else if (!bAuthor) comparison = -1;
253	        else comparison = compareStrings(aAuthor, bAuthor, sort.direction);
254	        break;
255	      }
256	    }
257	
258	    return comparison || a.uid.localeCompare(b.uid);
259	  });
260	
261	  return sorted.map((entry) => entry.result);
262	};
263	
264	export const searchDiscourseNodesWithMiniSearch = ({
265	  miniSearch,
266	  allResults,
267	  searchTerm,
268	  typeFilter,
269	}: {
270	  miniSearch: MiniSearch<MiniSearchDocument>;
271	  allResults: SearchResult[];
272	  searchTerm: string;
273	  typeFilter?: string[];
274	}): ScoredSearchResult[] => {
275	  const resultsByUid = new Map(
276	    allResults.map((result) => [result.uid, result]),
277	  );
278	  const allowedTypes = typeFilter?.length ? new Set(typeFilter) : null;
279	
280	  return miniSearch
281	    .search(searchTerm, {
282	      fields: ["title", "nodeTypeLabel"],
283	      ...DISCOURSE_NODE_MINI_SEARCH_OPTIONS,
284	      filter: allowedTypes
285	        ? (result) => allowedTypes.has(String(result.type))
286	        : undefined,
287	    })
288	    .filter((result) => result.score > DISCOURSE_NODE_MIN_SEARCH_SCORE)
289	    .slice(0, MAX_RESULTS)
290	    .map((result) => {
291	      const searchResult = resultsByUid.get(String(result.id));
292	      if (!searchResult) return null;
293	      return {
294	        result: searchResult,
295	        score: result.score,
296	        source: "miniSearch",
297	      };
298	    })
299	    .filter((entry): entry is ScoredSearchResult => !!entry);
300	};
  1	import { useEffect, useMemo, useState } from "react";
  2	import MiniSearch from "minisearch";
  3	import getDiscourseNodes from "~/utils/getDiscourseNodes";
  4	import { searchDiscourseNodes } from "~/utils/searchDiscourseNodes";
  5	import {
  6	  searchDiscourseNodesWithMiniSearch,
  7	  sortSearchResults,
  8	  type ScoredSearchResult,
  9	  type SearchResult,
 10	  type SortConfig,
 11	} from "./utils";
 12	
 13	export type SearchIndex = {
 14	  miniSearch: MiniSearch<SearchResult & { id: string }>;
 15	  allResults: SearchResult[];
 16	};
 17	
 18	type UseAdvancedNodeSearchResultsArgs = {
 19	  debouncedSearchTerm: string;
 20	  selectedNodeTypeIds: string[];
 21	  sort: SortConfig;
 22	  isIndexLoading: boolean;
 23	  indexError: boolean;
 24	  searchIndex: SearchIndex | null;
 25	  dockedQuery?: string;
 26	  dockedResults?: SearchResult[];
 27	};
 28	
 29	export const useAdvancedNodeSearchResults = ({
 30	  debouncedSearchTerm,
 31	  selectedNodeTypeIds,
 32	  sort,
 33	  isIndexLoading,
 34	  indexError,
 35	  searchIndex,
 36	  dockedQuery,
 37	  dockedResults,
 38	}: UseAdvancedNodeSearchResultsArgs): {
 39	  results: SearchResult[];
 40	  isSearching: boolean;
 41	} => {
 42	  // An empty persisted result set is not a usable cache: the docked panel also
 43	  // persists the transient [] published while an async search is in flight.
 44	  const hasUsableDockedResults = useMemo(
 45	    () =>
 46	      dockedQuery !== undefined &&
 47	      debouncedSearchTerm.trim() === dockedQuery.trim() &&
 48	      !!dockedResults &&
 49	      dockedResults.length > 0,
 50	    [debouncedSearchTerm, dockedQuery, dockedResults],
 51	  );
 52	
 53	  const [unsortedScoredResults, setUnsortedScoredResults] = useState<
 54	    ScoredSearchResult[]
 55	  >([]);
 56	  const [isSearching, setIsSearching] = useState(false);
 57	
 58	  useEffect(() => {
 59	    if (hasUsableDockedResults) {
 60	      setUnsortedScoredResults([]);
 61	      setIsSearching(false);
 62	      return;
 63	    }
 64	
 65	    if (!debouncedSearchTerm) {
 66	      setUnsortedScoredResults([]);
 67	      setIsSearching(false);
 68	      return;
 69	    }
 70	
 71	    if (isIndexLoading || indexError || !searchIndex) {
 72	      setUnsortedScoredResults([]);
 73	      setIsSearching(false);
 74	      return;
 75	    }
 76	
 77	    setUnsortedScoredResults([]);
 78	    setIsSearching(true);
 79	    let cancelled = false;
 80	    const typeFilter = selectedNodeTypeIds.length
 81	      ? selectedNodeTypeIds
 82	      : undefined;
 83	    const discourseNodes = getDiscourseNodes().filter(
 84	      (node) =>
 85	        node.backedBy === "user" &&
 86	        (!typeFilter || typeFilter.includes(node.type)),
 87	    );
 88	    const resultsByUid = new Map(
 89	      searchIndex.allResults.map((result) => [result.uid, result]),
 90	    );
 91	
 92	    const runMiniSearch = (): ScoredSearchResult[] =>
 93	      searchDiscourseNodesWithMiniSearch({
 94	        miniSearch: searchIndex.miniSearch,
 95	        allResults: searchIndex.allResults,
 96	        searchTerm: debouncedSearchTerm,
 97	        typeFilter,
 98	      });
 99	
100	    void searchDiscourseNodes({
101	      nodeTypes: discourseNodes,
102	      query: debouncedSearchTerm,
103	      resultsByUid,
104	      runMiniSearch,
105	    })
106	      .then((results) => {
107	        if (cancelled) return;
108	        setUnsortedScoredResults(results);
109	      })
110	      .catch(() => {
111	        if (cancelled) return;
112	        try {
113	          setUnsortedScoredResults(runMiniSearch());
114	        } catch {
115	          setUnsortedScoredResults([]);
116	        }
117	      })
118	      .finally(() => {
119	        if (!cancelled) setIsSearching(false);
120	      });
121	
122	    return () => {
123	      cancelled = true;
124	    };
125	  }, [
126	    debouncedSearchTerm,
127	    hasUsableDockedResults,
128	    indexError,
129	    isIndexLoading,
130	    searchIndex,
131	    selectedNodeTypeIds,
132	  ]);
133	
134	  const results = useMemo(
135	    () => sortSearchResults({ scoredResults: unsortedScoredResults, sort }),
136	    [unsortedScoredResults, sort],
137	  );
138	
139	  if (hasUsableDockedResults && dockedResults) {
140	    return { results: dockedResults, isSearching: false };
141	  }
142	
143	  return { results, isSearching };
144	};

