152	const AdvancedNodeSearchDialog = ({
153	  isOpen,
154	  onClose,
155	}: RoamOverlayProps<Props>) => {
156	  const [searchTerm, setSearchTerm] = useState("");
157	  const [debouncedSearchTerm, setDebouncedSearchTerm] = useState("");
158	  const [isIndexLoading, setIsIndexLoading] = useState(false);
159	  const [indexError, setIndexError] = useState(false);
160	  const [activeIndex, setActiveIndex] = useState(0);
161	  const [searchIndex, setSearchIndex] = useState<SearchIndex | null>(null);
162	  const [sort, setSort] = useState<SortConfig>(DEFAULT_SORT_CONFIG);
163	  const [discourseNodes, setDiscourseNodes] = useState<DiscourseNode[]>([]);
164	  const [selectedNodeTypeIds, setSelectedNodeTypeIds] = useState<string[]>([]);
165	  const [isTypeFilterPopoverOpen, setIsTypeFilterPopoverOpen] = useState(false);
166	  const resultsPanelRef = useRef<HTMLDivElement | null>(null);
167	  const inputRef = useRef<HTMLInputElement | null>(null);
168	  const [insertTarget, setInsertTarget] = useState<InsertTarget | null>(null);
169	
170	  const nodeConfigByType = Object.fromEntries(
171	    discourseNodes.map((node) => [node.type, node]),
